css:
/* ===========================================================
   COPIED VERBATIM FROM THE LIVE BLOG LISTING PAGE.
   Do not alter, this is what keeps the listing consistent.
   =========================================================== */
:root{
  --primary:#016edc; --primary-dark:#014284;
  --navy:#1c293f; --deep:#00334e; --accent:#ffa800;
  --ink:#1c293f; --muted:#5b6470;
  --light:#f0f0fa; --soft:#f5f5f5; --line:#e5e7eb; --white:#fff;
  --pill:60px; --r:16px; --r-lg:30px;
  --shadow:0 20px 50px #1c293f1a; --shadow-sm:0 8px 24px #1c293f14;
  --max:1200px;
  --font:"Fustat",-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
}
*{box-sizing:border-box}
html,body{margin:0}
body{font-family:var(--font);background:var(--white);color:var(--ink)}

/* shell */
.wrap{max-width:var(--max);margin:0 auto;padding:0 24px}
.narrowx{max-width:820px}
.sec{padding:90px 0;position:relative}
.sec.alt{background:var(--soft)}
.shead{text-align:center;max-width:720px;margin:0 auto 54px}
.shead.center{text-align:center}
.h1{font-family:var(--font);font-size:2.25rem;line-height:1.25;font-weight:800;letter-spacing:-.025em;color:var(--navy)}
.hh{color:var(--navy);letter-spacing:-.02em;margin-bottom:8px;font-family:Fustat,sans-serif;font-weight:800;line-height:1.16}

/* category filter */
.category-filter{border-bottom:2px solid var(--line);scroll-behavior:smooth;gap:12px;margin-bottom:32px;padding-bottom:16px;display:flex;overflow-x:auto}
.category-filter::-webkit-scrollbar{height:6px}
.category-filter::-webkit-scrollbar-track{background:0 0}
.category-filter::-webkit-scrollbar-thumb{background:var(--primary);border-radius:3px}
.category-btn{border:1px solid var(--line);color:var(--ink);cursor:pointer;white-space:nowrap;background:#fff;border-radius:24px;padding:10px 20px;font-size:.95rem;font-weight:500;transition:all .3s}
.category-btn:hover{border-color:var(--primary);color:var(--primary)}
.category-btn.active{background:var(--primary);color:#fff;border-color:var(--primary)}

/* grid + cards (later declarations, the ones that win on the live page) */
.blog-grid{grid-template-columns:repeat(auto-fill,minmax(300px,1fr));gap:28px;margin-top:40px;display:grid}
.blog-card{border-radius:var(--r-lg);background:#fff;flex-direction:column;transition:all .3s;display:flex;overflow:hidden;box-shadow:0 2px 8px #1c293f14}
.blog-card:hover{transform:translateY(-4px);box-shadow:0 8px 24px #1c293f1f}
.blog-card-image-link{background:var(--soft);height:200px;display:block;position:relative;overflow:hidden}
.blog-card-image{object-fit:cover;width:100%;height:100%;transition:transform .3s}
.blog-card:hover .blog-card-image{transform:scale(1.05)}
.blog-card-category{background:var(--primary);color:#fff;letter-spacing:.5px;border-radius:4px;padding:6px 12px;font-size:.75rem;font-weight:700;position:absolute;top:12px;right:12px}
.blog-card-content{flex-direction:column;flex:1;padding:20px;display:flex}
.blog-card-title-link{color:inherit;text-decoration:none}
.blog-card-title{color:var(--navy);margin:0 0 8px;font-size:1.1rem;font-weight:700;line-height:1.4;transition:color .3s}
.blog-card-title-link:hover .blog-card-title{color:var(--primary)}
.blog-card-date{color:var(--muted);margin:0 0 12px;font-size:.85rem;font-weight:500}
.blog-card-excerpt{color:var(--ink);flex:1;margin:0 0 16px;font-size:.95rem;line-height:1.6}
.blog-card-read-more{color:var(--primary);border-bottom:2px solid var(--primary);align-self:flex-start;padding-bottom:2px;font-size:.95rem;font-weight:600;text-decoration:none;transition:all .3s}
.blog-card-read-more:hover{color:var(--navy);border-bottom-color:var(--navy)}

/* the three responsive rules the live page has, verbatim */
@media (max-width:980px){ .blog-grid{grid-template-columns:repeat(2,1fr)} }
@media (max-width:768px){ .blog-grid{grid-template-columns:repeat(auto-fill,minmax(250px,1fr));gap:20px} }
@media (max-width:600px){ .sec{padding:64px 0} .blog-grid{grid-template-columns:1fr} }
